import type { ReactNode } from "react";

/** @deprecated Not used; the search index format is `SiteMapPage` (see `compileSearchIndex`) */
export type SiteSearchRecord = {
  path: string;
  section?: string | undefined;
  text: string;
  title: string;
};

/** Visual style of a callout or button */
export type Intent = "danger" | "none" | "primary" | "success" | "warning";

/** A block of a description generated by `compileDocs` */
export type Section = {
  /** Content is syntax highlighted code */
  code?: boolean | undefined;
  /** HTML */
  content: string;
  /** Content is a callout with this intent */
  intent?: Intent | undefined;
};

/** Documentation for one prop, generated by `compileDocs` */
export type ComponentPropMetadata = {
  description: Section[];
  /** Syntax highlighted signature, e.g. `size?: "small" | "large" = "small"` */
  html: string;
  name: string;
  required: boolean;
};

/** Documentation for a component's props, generated by `compileDocs`; rendered by `ComponentProps` */
export type ComponentMetadata = {
  description: Section[];
  /** Source file, relative to the repository root */
  filePath: string;
  name: string;
  props: {
    [name: string]: ComponentPropMetadata;
  };
};

/** Documentation for one method of an imperative API, generated by `compileDocs` */
export type ImperativeHandleMethodMetadata = {
  description: Section[];
  /** Syntax highlighted signature */
  html: string;
  name: string;
};

/** Documentation for an imperative API, generated by `compileDocs`; rendered by `ImperativeHandle` */
export type ImperativeHandleMetadata = {
  description: Section[];
  /** Source file, relative to the repository root */
  filePath: string;
  name: string;
  methods: ImperativeHandleMethodMetadata[];
};

/** A question and answer shown on the "Common questions" page */
export type CommonQuestion = {
  answer: ReactNode;
  /** Unique id, used to link directly to the question (e.g. "/common-questions#my-id") */
  id: string;
  question: ReactNode;
};

/** A link to a page in the site navigation */
export type NavLinkConfig<Path extends string = string> = {
  /** Nested pages, rendered indented beneath this link */
  children?: NavLinkConfig<Path>[] | undefined;
  /** Shorter label shown in the sidebar; defaults to `title` (which is still used for previous/next links and search) */
  navTitle?: string | undefined;
  path: Path;
  title: string;
};

/** A titled group of links within a nav section (e.g. "Guides" or "Components"); collapsed unless it contains the current page */
export type NavGroupConfig<Path extends string = string> = {
  links: NavLinkConfig<Path>[];
  title: string;
};

/** A titled group of links in the site navigation; collapsed unless it contains the current page */
export type NavSectionConfig<Path extends string = string> = {
  links: Array<NavGroupConfig<Path> | NavLinkConfig<Path>>;
  title: string;
};

/**
 * Site navigation, in reading order.
 * Drives both the sidebar and the previous/next links at the bottom of each page.
 */
export type NavConfig<Path extends string = string> = Array<
  NavLinkConfig<Path> | NavSectionConfig<Path>
>;
